function unitFor(id: number): number {
  if (id <= 20) return 12;
  if (id <= 24) return 4;
  if (id <= 37) return 5;
  if (id <= 65) return 6;
  if (id <= 74) return 7;
  if (id <= 82) return 8;
  if (id <= 125) return 9;
  return 10;
}

const norm = (s: string) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");

function syndromeFor(qa: [string, string][]): string | undefined {
  for (const [, a] of qa) {
    const na = norm(a);
    const hit = SYNDROMES.find((s) => na.includes(norm(s.name.replace(/ \(.*\)/, ""))));
    if (hit) return hit.id;
  }
  return undefined;
}

export const CASES: ClinicalCase[] = raw.map(([title, vignette, qa], i) => {
  const id = i + 1;
  const unitId = unitFor(id);
  return {
    id,
    title,
    vignette,
    qa: qa.map(([q, a]) => ({ q, a })),
    unitId,
    syndromeId: syndromeFor(qa),
    difficulty: unitId === 12 ? "Difícil" : qa.length >= 3 ? "Media" : "Fácil",
  };
});

export const getCase = (id: number) => CASES.find((c) => c.id === id);
